INSERT INTO dimensions (rubric_version, key, name, description, display_order, radar_order) VALUES ('1.0', 'story', 'Story & Character Investment', 'How effectively does the game create and sustain narrative/character investment on its own terms?', 1, 1) ON CONFLICT (rubric_version, key) DO NOTHING;
INSERT INTO subcriteria (dimension_id, key, name, description, display_order) SELECT id, 'story_hook', 'Story Hook & Stakes', 'Does the central situation create a reason to care or continue?', 1 FROM dimensions WHERE rubric_version = '1.0' AND key = 'story' ON CONFLICT (dimension_id, key) DO NOTHING;
INSERT INTO subcriteria (dimension_id, key, name, description, display_order) SELECT id, 'character_investment', 'Character Investment', 'Are central characters legible, compelling, affecting or interesting enough to carry the experience?', 2 FROM dimensions WHERE rubric_version = '1.0' AND key = 'story' ON CONFLICT (dimension_id, key) DO NOTHING;
INSERT INTO subcriteria (dimension_id, key, name, description, display_order) SELECT id, 'narrative_coherence', 'Narrative Coherence', 'Do plot, motivations and world rules hold together at the level the game requires?', 3 FROM dimensions WHERE rubric_version = '1.0' AND key = 'story' ON CONFLICT (dimension_id, key) DO NOTHING;
INSERT INTO subcriteria (dimension_id, key, name, description, display_order) SELECT id, 'narrative_momentum', 'Narrative Momentum & Payoff', 'Does the story develop rather than merely exist? Are setup and payoff proportionate?', 4 FROM dimensions WHERE rubric_version = '1.0' AND key = 'story' ON CONFLICT (dimension_id, key) DO NOTHING;
INSERT INTO subcriteria (dimension_id, key, name, description, display_order) SELECT id, 'world_lore_integration', 'World/Lore Integration', 'Does worldbuilding, lore, continuity or environmental narrative meaningfully strengthen investment?', 5 FROM dimensions WHERE rubric_version = '1.0' AND key = 'story' ON CONFLICT (dimension_id, key) DO NOTHING;
INSERT INTO dimensions (rubric_version, key, name, description, display_order, radar_order) VALUES ('1.0', 'execution', 'Execution & Polish', 'How reliably and competently does the finished product deliver what it is trying to do?', 2, 6) ON CONFLICT (rubric_version, key) DO NOTHING;
INSERT INTO subcriteria (dimension_id, key, name, description, display_order) SELECT id, 'dramatic_execution', 'Dramatic/Writing Execution', 'Dialogue, scene construction, delivery and dramatic competence relative to the game’s intent.', 1 FROM dimensions WHERE rubric_version = '1.0' AND key = 'execution' ON CONFLICT (dimension_id, key) DO NOTHING;
INSERT INTO subcriteria (dimension_id, key, name, description, display_order) SELECT id, 'gameplay_execution', 'Gameplay Execution', 'Responsiveness, clarity, consistency, animation/feedback and implementation quality.', 2 FROM dimensions WHERE rubric_version = '1.0' AND key = 'execution' ON CONFLICT (dimension_id, key) DO NOTHING;
INSERT INTO subcriteria (dimension_id, key, name, description, display_order) SELECT id, 'technical_stability', 'Technical Stability', 'Performance, bugs, crashes, streaming/stutter and major technical problems, with platform context where necessary.', 3 FROM dimensions WHERE rubric_version = '1.0' AND key = 'execution' ON CONFLICT (dimension_id, key) DO NOTHING;
INSERT INTO subcriteria (dimension_id, key, name, description, display_order) SELECT id, 'production_cohesion', 'Production Cohesion', 'Do art, audio, UX, content and systems feel finished and coherent rather than visibly compromised?', 4 FROM dimensions WHERE rubric_version = '1.0' AND key = 'execution' ON CONFLICT (dimension_id, key) DO NOTHING;
INSERT INTO subcriteria (dimension_id, key, name, description, display_order) SELECT id, 'consistency', 'Consistency', 'Does quality hold across the runtime, or do major sections/systems collapse?', 5 FROM dimensions WHERE rubric_version = '1.0' AND key = 'execution' ON CONFLICT (dimension_id, key) DO NOTHING;
INSERT INTO dimensions (rubric_version, key, name, description, display_order, radar_order) VALUES ('1.0', 'structure', 'Structure & Focus', 'How well is the game’s form organized around its intended experience?', 3, 7) ON CONFLICT (rubric_version, key) DO NOTHING;
