INSERT INTO subcriteria (dimension_id, key, name, description, display_order) SELECT id, 'navigation_legibility', 'Navigation & Information Legibility', 'Does the game provide enough environmental, interface or systemic information for its intended navigation model to be learnable and coherent? Absence of a map or quest marker is not inherently a penalty.', 2 FROM dimensions WHERE rubric_version = '1.0' AND key = 'structure' ON CONFLICT (dimension_id, key) DO NOTHING;
INSERT INTO subcriteria (dimension_id, key, name, description, display_order) SELECT id, 'repetition_control', 'Repetition Control', 'Does the structure reuse content intelligently, or lean on filler/repetition beyond its value?', 3 FROM dimensions WHERE rubric_version = '1.0' AND key = 'structure' ON CONFLICT (dimension_id, key) DO NOTHING;
INSERT INTO subcriteria (dimension_id, key, name, description, display_order) SELECT id, 'ux_friction', 'UX / Interaction Friction', 'Menus, inventory, traversal, checkpointing, onboarding and interface friction.', 4 FROM dimensions WHERE rubric_version = '1.0' AND key = 'structure' ON CONFLICT (dimension_id, key) DO NOTHING;
INSERT INTO subcriteria (dimension_id, key, name, description, display_order) SELECT id, 'content_focus', 'Content Focus', 'How much of the game feels purposeful versus padded, duplicated or obligatory?', 5 FROM dimensions WHERE rubric_version = '1.0' AND key = 'structure' ON CONFLICT (dimension_id, key) DO NOTHING;
