INSERT INTO subcriteria (dimension_id, key, name, description, display_order) SELECT id, 'toolset_depth', 'Toolset / Choice Depth', 'Are there interesting tactical, strategic, expressive or systemic options appropriate to the genre?', 2 FROM dimensions WHERE rubric_version = '1.0' AND key = 'agency' ON CONFLICT (dimension_id, key) DO NOTHING;
INSERT INTO subcriteria (dimension_id, key, name, description, display_order) SELECT id, 'reward_rhythm', 'Reward Rhythm', 'Does action produce satisfying feedback, progress, discovery, mastery or narrative reward?', 3 FROM dimensions WHERE rubric_version = '1.0' AND key = 'agency' ON CONFLICT (dimension_id, key) DO NOTHING;
INSERT INTO subcriteria (dimension_id, key, name, description, display_order) SELECT id, 'failure_fairness', 'Failure / Friction Fairness', 'When the game resists the player, is the resistance readable and proportionate to its design?', 4 FROM dimensions WHERE rubric_version = '1.0' AND key = 'agency' ON CONFLICT (dimension_id, key) DO NOTHING;
