INSERT INTO subcriteria (dimension_id, key, name, description, display_order) SELECT id, 'opening_effectiveness', 'Opening Effectiveness', 'How effectively does the game establish its loop, stakes or appeal?', 1 FROM dimensions WHERE rubric_version = '1.0' AND key = 'pacing' ON CONFLICT (dimension_id, key) DO NOTHING;
INSERT INTO subcriteria (dimension_id, key, name, description, display_order) SELECT id, 'momentum_maintenance', 'Momentum Maintenance', 'Does the experience continue developing or repeatedly stall?', 2 FROM dimensions WHERE rubric_version = '1.0' AND key = 'pacing' ON CONFLICT (dimension_id, key) DO NOTHING;
