INSERT INTO subcriteria (dimension_id, key, name, description, display_order) SELECT id, 'mood_strength', 'Mood Strength', 'Does the game sustain an intentional emotional/sensory tone?', 2 FROM dimensions WHERE rubric_version = '1.0' AND key = 'atmosphere' ON CONFLICT (dimension_id, key) DO NOTHING;
