INSERT INTO dimensions (rubric_version, key, name, description, display_order, radar_order) VALUES ('1.0', 'thematic', 'Thematic & Emotional Impact', 'How effectively does the game create emotional or thematic meaning beyond functional plot progression?', 7, 2) ON CONFLICT (rubric_version, key) DO NOTHING;
