INSERT INTO subcriteria (dimension_id, key, name, description, display_order) SELECT id, 'emotional_power', 'Emotional Power', 'Do characters/events/systems create genuine emotional response appropriate to the intent?', 2 FROM dimensions WHERE rubric_version = '1.0' AND key = 'thematic' ON CONFLICT (dimension_id, key) DO NOTHING;
