INSERT INTO games (slug, canonical_title, summary, developer_text, publisher_text, first_release_date, release_status) VALUES ('alan-wake-2', 'Alan Wake 2', 'A survival-horror sequel in which an FBI agent investigating ritual killings in the Pacific Northwest and a writer trapped inside his own manuscript work the same case from two sides.', 'Remedy Entertainment', 'Epic Games Publishing', '2023-10-27', 'released') ON CONFLICT (slug) DO NOTHING;
INSERT INTO game_platforms (game_id, platform_id) SELECT g.id, p.id FROM games g, platforms p WHERE g.slug = 'alan-wake-2' AND p.slug = 'ps5' ON CONFLICT DO NOTHING;
INSERT INTO game_platforms (game_id, platform_id) SELECT g.id, p.id FROM games g, platforms p WHERE g.slug = 'alan-wake-2' AND p.slug = 'xbox-series' ON CONFLICT DO NOTHING;
INSERT INTO game_platforms (game_id, platform_id) SELECT g.id, p.id FROM games g, platforms p WHERE g.slug = 'alan-wake-2' AND p.slug = 'pc' ON CONFLICT DO NOTHING;
INSERT INTO game_aliases (game_id, alias, alias_type) SELECT id, 'AW2', 'common' FROM games WHERE slug = 'alan-wake-2' ON CONFLICT DO NOTHING;
INSERT INTO game_aliases (game_id, alias, alias_type) SELECT id, 'Alan Wake II', 'common' FROM games WHERE slug = 'alan-wake-2' ON CONFLICT DO NOTHING;
INSERT INTO evaluations (game_id, rubric_version, version_number, edition_scope, mode_scope, platform_scope, build_or_patch_scope, current_state_cutoff_at, status, evidence_status, confidence, evidence_cutoff_at, release_context, one_line_experience, primary_pull, primary_risk, platform_warning, score_provenance, provenance_note, published_at, change_summary) SELECT id, '1.0', 1, 'Base game', 'Single-player campaign', ARRAY['PlayStation 5', 'Xbox Series X|S', 'PC'], 'Current retail build, post-launch updates applied', NULL, 'published', 'verified', 'high', '2026-08-06', 'Post-release', 'A deliberately slow horror mystery told from two sides at once, where assembling the story is the main act of play and combat is a rationed interruption.', 'A horror narrative that uses the medium as its instrument — a case you physically assemble, a manuscript you rewrite, and live action folded into the game rather than bolted onto it.', 'Combat is scarce, stiff and deliberately unglamorous; the long investigative stretches between fights ask for patience rather than reflexes.', 'PC performance varies sharply with ray-tracing and path-tracing settings. The console versions are the stable reference experience.', 'derived_pending_round_1_reconciliation', 'Scores derived from Rubric v1.0 pending reconciliation with the Calibration Round 1 report.', '2026-08-06'::timestamptz, NULL FROM games WHERE slug = 'alan-wake-2';
INSERT INTO subcriterion_scores (evaluation_id, subcriterion_id, score, rationale, platform_note) SELECT (SELECT e.id FROM evaluations e JOIN games g ON g.id = e.game_id WHERE g.slug = 'alan-wake-2' AND e.version_number = 1), s.id, 2, 'Two investigations — a federal agent working ritual killings and a writer escaping a manuscript that is authoring reality — are legible within minutes and immediately imply each other.', NULL FROM subcriteria s JOIN dimensions d ON d.id = s.dimension_id WHERE d.rubric_version = '1.0' AND d.key = 'story' AND s.key = 'story_hook';
INSERT INTO subcriterion_scores (evaluation_id, subcriterion_id, score, rationale, platform_note) SELECT (SELECT e.id FROM evaluations e JOIN games g ON g.id = e.game_id WHERE g.slug = 'alan-wake-2' AND e.version_number = 1), s.id, 2, 'Saga Anderson is a rare thing in horror: a competent professional with a life outside the plot. Wake''s self-loathing writerly vanity gives the second half a genuinely different voice rather than a second protagonist skin.', NULL FROM subcriteria s JOIN dimensions d ON d.id = s.dimension_id WHERE d.rubric_version = '1.0' AND d.key = 'story' AND s.key = 'character_investment';
INSERT INTO subcriterion_scores (evaluation_id, subcriterion_id, score, rationale, platform_note) SELECT (SELECT e.id FROM evaluations e JOIN games g ON g.id = e.game_id WHERE g.slug = 'alan-wake-2' AND e.version_number = 1), s.id, 1.5, 'The internal rules of the Dark Place are applied consistently, but the game deliberately withholds resolution and ends on an unclosed loop. Coherent at the level it requires, not at the level a viewer wanting closure would want.', NULL FROM subcriteria s JOIN dimensions d ON d.id = s.dimension_id WHERE d.rubric_version = '1.0' AND d.key = 'story' AND s.key = 'narrative_coherence';
INSERT INTO subcriterion_scores (evaluation_id, subcriterion_id, score, rationale, platform_note) SELECT (SELECT e.id FROM evaluations e JOIN games g ON g.id = e.game_id WHERE g.slug = 'alan-wake-2' AND e.version_number = 1), s.id, 2, 'Each chapter reframes what the previous one meant, and the two storylines converge rather than merely alternate. Setup and payoff stay proportionate across a long runtime.', NULL FROM subcriteria s JOIN dimensions d ON d.id = s.dimension_id WHERE d.rubric_version = '1.0' AND d.key = 'story' AND s.key = 'narrative_momentum';
INSERT INTO subcriterion_scores (evaluation_id, subcriterion_id, score, rationale, platform_note) SELECT (SELECT e.id FROM evaluations e JOIN games g ON g.id = e.game_id WHERE g.slug = 'alan-wake-2' AND e.version_number = 1), s.id, 2, 'Manuscript pages, TV segments, radio and cross-title continuity all feed the central mystery instead of sitting beside it as optional collectible fiction.', NULL FROM subcriteria s JOIN dimensions d ON d.id = s.dimension_id WHERE d.rubric_version = '1.0' AND d.key = 'story' AND s.key = 'world_lore_integration';
INSERT INTO subcriterion_scores (evaluation_id, subcriterion_id, score, rationale, platform_note) SELECT (SELECT e.id FROM evaluations e JOIN games g ON g.id = e.game_id WHERE g.slug = 'alan-wake-2' AND e.version_number = 1), s.id, 2, 'Scene construction and performance are exceptional for the medium, and the register shifts — procedural, pulp, musical, comic — are controlled rather than indulgent.', NULL FROM subcriteria s JOIN dimensions d ON d.id = s.dimension_id WHERE d.rubric_version = '1.0' AND d.key = 'execution' AND s.key = 'dramatic_execution';
INSERT INTO subcriterion_scores (evaluation_id, subcriterion_id, score, rationale, platform_note) SELECT (SELECT e.id FROM evaluations e JOIN games g ON g.id = e.game_id WHERE g.slug = 'alan-wake-2' AND e.version_number = 1), s.id, 1.5, 'Shooting is readable and weighty but intentionally sluggish; enemy tracking and the dodge can feel imprecise in crowded encounters. Implementation is competent, not a strength.', NULL FROM subcriteria s JOIN dimensions d ON d.id = s.dimension_id WHERE d.rubric_version = '1.0' AND d.key = 'execution' AND s.key = 'gameplay_execution';
INSERT INTO subcriterion_scores (evaluation_id, subcriterion_id, score, rationale, platform_note) SELECT (SELECT e.id FROM evaluations e JOIN games g ON g.id = e.game_id WHERE g.slug = 'alan-wake-2' AND e.version_number = 1), s.id, 1.5, 'Console builds are stable and well-optimised. PC is demanding and highly settings-sensitive at ray-traced presets, which is why the platform warning exists.', 'PS5 / Xbox Series X|S: stable. PC: heavy GPU demand at RT/path-traced settings.' FROM subcriteria s JOIN dimensions d ON d.id = s.dimension_id WHERE d.rubric_version = '1.0' AND d.key = 'execution' AND s.key = 'technical_stability';
INSERT INTO subcriterion_scores (evaluation_id, subcriterion_id, score, rationale, platform_note) SELECT (SELECT e.id FROM evaluations e JOIN games g ON g.id = e.game_id WHERE g.slug = 'alan-wake-2' AND e.version_number = 1), s.id, 2, 'Art, sound, live action, UI and lighting are unusually unified; the Mind Place and the Writer''s Room feel authored by the same hand as the world outside them.', NULL FROM subcriteria s JOIN dimensions d ON d.id = s.dimension_id WHERE d.rubric_version = '1.0' AND d.key = 'execution' AND s.key = 'production_cohesion';
INSERT INTO subcriterion_scores (evaluation_id, subcriterion_id, score, rationale, platform_note) SELECT (SELECT e.id FROM evaluations e JOIN games g ON g.id = e.game_id WHERE g.slug = 'alan-wake-2' AND e.version_number = 1), s.id, 1.5, 'Quality holds across a long runtime, but the combat encounters in the later Dark Place chapters lean on repetition the rest of the game avoids.', NULL FROM subcriteria s JOIN dimensions d ON d.id = s.dimension_id WHERE d.rubric_version = '1.0' AND d.key = 'execution' AND s.key = 'consistency';
INSERT INTO subcriterion_scores (evaluation_id, subcriterion_id, score, rationale, platform_note) SELECT (SELECT e.id FROM evaluations e JOIN games g ON g.id = e.game_id WHERE g.slug = 'alan-wake-2' AND e.version_number = 1), s.id, 2, 'The player-chosen order of the two campaigns is a structural argument, not a convenience: which story you advance changes what the other half means when you return to it.', NULL FROM subcriteria s JOIN dimensions d ON d.id = s.dimension_id WHERE d.rubric_version = '1.0' AND d.key = 'structure' AND s.key = 'structural_intentionality';
INSERT INTO subcriterion_scores (evaluation_id, subcriterion_id, score, rationale, platform_note) SELECT (SELECT e.id FROM evaluations e JOIN games g ON g.id = e.game_id WHERE g.slug = 'alan-wake-2' AND e.version_number = 1), s.id, 1.5, 'Hub areas are hand-authored and readable, with clear landmarks. The Dark Place intentionally disorients, and a few late routes are harder to parse than the design needs them to be.', NULL FROM subcriteria s JOIN dimensions d ON d.id = s.dimension_id WHERE d.rubric_version = '1.0' AND d.key = 'structure' AND s.key = 'navigation_legibility';
INSERT INTO subcriterion_scores (evaluation_id, subcriterion_id, score, rationale, platform_note) SELECT (SELECT e.id FROM evaluations e JOIN games g ON g.id = e.game_id WHERE g.slug = 'alan-wake-2' AND e.version_number = 1), s.id, 1.5, 'Areas are revisited with meaningful transformation rather than re-run, though the Taken encounters themselves recycle a small set of patterns.', NULL FROM subcriteria s JOIN dimensions d ON d.id = s.dimension_id WHERE d.rubric_version = '1.0' AND d.key = 'structure' AND s.key = 'repetition_control';
INSERT INTO subcriterion_scores (evaluation_id, subcriterion_id, score, rationale, platform_note) SELECT (SELECT e.id FROM evaluations e JOIN games g ON g.id = e.game_id WHERE g.slug = 'alan-wake-2' AND e.version_number = 1), s.id, 1.5, 'The Mind Place and Plot Board are inspired but add navigation steps to routine actions; inventory management is functional but fiddly under pressure.', NULL FROM subcriteria s JOIN dimensions d ON d.id = s.dimension_id WHERE d.rubric_version = '1.0' AND d.key = 'structure' AND s.key = 'ux_friction';
INSERT INTO subcriterion_scores (evaluation_id, subcriterion_id, score, rationale, platform_note) SELECT (SELECT e.id FROM evaluations e JOIN games g ON g.id = e.game_id WHERE g.slug = 'alan-wake-2' AND e.version_number = 1), s.id, 2, 'There is essentially no filler. Optional content — nursery rhymes, cult stashes, coffee thermoses — is short, thematically placed and never gates the campaign.', NULL FROM subcriteria s JOIN dimensions d ON d.id = s.dimension_id WHERE d.rubric_version = '1.0' AND d.key = 'structure' AND s.key = 'content_focus';
INSERT INTO subcriterion_scores (evaluation_id, subcriterion_id, score, rationale, platform_note) SELECT (SELECT e.id FROM evaluations e JOIN games g ON g.id = e.game_id WHERE g.slug = 'alan-wake-2' AND e.version_number = 1), s.id, 1.5, 'Light-then-shoot combat gives input real consequence, but the character''s mobility is deliberately constrained and the margin for reaction is narrow.', NULL FROM subcriteria s JOIN dimensions d ON d.id = s.dimension_id WHERE d.rubric_version = '1.0' AND d.key = 'agency' AND s.key = 'moment_to_moment';
INSERT INTO subcriterion_scores (evaluation_id, subcriterion_id, score, rationale, platform_note) SELECT (SELECT e.id FROM evaluations e JOIN games g ON g.id = e.game_id WHERE g.slug = 'alan-wake-2' AND e.version_number = 1), s.id, 1.5, 'A small arsenal plus flares, flashbangs and the flashlight covers the encounter design, but there is little room for expression or personal approach.', NULL FROM subcriteria s JOIN dimensions d ON d.id = s.dimension_id WHERE d.rubric_version = '1.0' AND d.key = 'agency' AND s.key = 'toolset_depth';
INSERT INTO subcriterion_scores (evaluation_id, subcriterion_id, score, rationale, platform_note) SELECT (SELECT e.id FROM evaluations e JOIN games g ON g.id = e.game_id WHERE g.slug = 'alan-wake-2' AND e.version_number = 1), s.id, 1.5, 'The strongest rewards are narrative and investigative — a case-board connection resolving — rather than mechanical. Weapon upgrades are modest and slow.', NULL FROM subcriteria s JOIN dimensions d ON d.id = s.dimension_id WHERE d.rubric_version = '1.0' AND d.key = 'agency' AND s.key = 'reward_rhythm';
INSERT INTO subcriterion_scores (evaluation_id, subcriterion_id, score, rationale, platform_note) SELECT (SELECT e.id FROM evaluations e JOIN games g ON g.id = e.game_id WHERE g.slug = 'alan-wake-2' AND e.version_number = 1), s.id, 1.5, 'Checkpointing is generous and death costs little, though ambushes in tight geometry can feel arbitrary rather than readable.', NULL FROM subcriteria s JOIN dimensions d ON d.id = s.dimension_id WHERE d.rubric_version = '1.0' AND d.key = 'agency' AND s.key = 'failure_fairness';
INSERT INTO subcriterion_scores (evaluation_id, subcriterion_id, score, rationale, platform_note) SELECT (SELECT e.id FROM evaluations e JOIN games g ON g.id = e.game_id WHERE g.slug = 'alan-wake-2' AND e.version_number = 1), s.id, 1.5, 'Resource scarcity is calibrated so the player is pressured but never helpless. The game is a survival horror that lets you fight, not one that removes the option.', NULL FROM subcriteria s JOIN dimensions d ON d.id = s.dimension_id WHERE d.rubric_version = '1.0' AND d.key = 'agency' AND s.key = 'capability_balance';
INSERT INTO subcriterion_scores (evaluation_id, subcriterion_id, score, rationale, platform_note) SELECT (SELECT e.id FROM evaluations e JOIN games g ON g.id = e.game_id WHERE g.slug = 'alan-wake-2' AND e.version_number = 1), s.id, 1.5, 'The opening establishes tone and place superbly but takes its time reaching the loop the rest of the game runs on.', NULL FROM subcriteria s JOIN dimensions d ON d.id = s.dimension_id WHERE d.rubric_version = '1.0' AND d.key = 'pacing' AND s.key = 'opening_effectiveness';
INSERT INTO subcriterion_scores (evaluation_id, subcriterion_id, score, rationale, platform_note) SELECT (SELECT e.id FROM evaluations e JOIN games g ON g.id = e.game_id WHERE g.slug = 'alan-wake-2' AND e.version_number = 1), s.id, 1.5, 'Momentum is sustained by escalating revelations, with occasional stalls where an investigation gate requires backtracking for a single item.', NULL FROM subcriteria s JOIN dimensions d ON d.id = s.dimension_id WHERE d.rubric_version = '1.0' AND d.key = 'pacing' AND s.key = 'momentum_maintenance';
INSERT INTO subcriterion_scores (evaluation_id, subcriterion_id, score, rationale, platform_note) SELECT (SELECT e.id FROM evaluations e JOIN games g ON g.id = e.game_id WHERE g.slug = 'alan-wake-2' AND e.version_number = 1), s.id, 2, 'Roughly 20 hours, and the length is structurally necessary — the dual-campaign design does not work at half the size.', NULL FROM subcriteria s JOIN dimensions d ON d.id = s.dimension_id WHERE d.rubric_version = '1.0' AND d.key = 'pacing' AND s.key = 'runtime_justification';
INSERT INTO subcriterion_scores (evaluation_id, subcriterion_id, score, rationale, platform_note) SELECT (SELECT e.id FROM evaluations e JOIN games g ON g.id = e.game_id WHERE g.slug = 'alan-wake-2' AND e.version_number = 1), s.id, 1.5, 'Chapters make clean stopping points, though the tension design rewards longer uninterrupted sittings than a short-session player can usually give it.', NULL FROM subcriteria s JOIN dimensions d ON d.id = s.dimension_id WHERE d.rubric_version = '1.0' AND d.key = 'pacing' AND s.key = 'session_rhythm';
INSERT INTO subcriterion_scores (evaluation_id, subcriterion_id, score, rationale, platform_note) SELECT (SELECT e.id FROM evaluations e JOIN games g ON g.id = e.game_id WHERE g.slug = 'alan-wake-2' AND e.version_number = 1), s.id, 1.5, 'Very little downtime, but a substantial share of the runtime is walking, reading and looking, which is deliberate rather than dense.', NULL FROM subcriteria s JOIN dimensions d ON d.id = s.dimension_id WHERE d.rubric_version = '1.0' AND d.key = 'pacing' AND s.key = 'content_density';
INSERT INTO subcriterion_scores (evaluation_id, subcriterion_id, score, rationale, platform_note) SELECT (SELECT e.id FROM evaluations e JOIN games g ON g.id = e.game_id WHERE g.slug = 'alan-wake-2' AND e.version_number = 1), s.id, 2, 'Bright Falls, Watery and Cauldron Lake are specific, inhabited and geographically coherent; the Dark Place is a recognisable New York rendered as a recurring nightmare.', NULL FROM subcriteria s JOIN dimensions d ON d.id = s.dimension_id WHERE d.rubric_version = '1.0' AND d.key = 'atmosphere' AND s.key = 'sense_of_place';
INSERT INTO subcriterion_scores (evaluation_id, subcriterion_id, score, rationale, platform_note) SELECT (SELECT e.id FROM evaluations e JOIN games g ON g.id = e.game_id WHERE g.slug = 'alan-wake-2' AND e.version_number = 1), s.id, 2, 'Dread is sustained continuously rather than delivered in shocks, and it survives even the game''s comic and musical detours.', NULL FROM subcriteria s JOIN dimensions d ON d.id = s.dimension_id WHERE d.rubric_version = '1.0' AND d.key = 'atmosphere' AND s.key = 'mood_strength';
INSERT INTO subcriterion_scores (evaluation_id, subcriterion_id, score, rationale, platform_note) SELECT (SELECT e.id FROM evaluations e JOIN games g ON g.id = e.game_id WHERE g.slug = 'alan-wake-2' AND e.version_number = 1), s.id, 2, 'Lighting-as-mechanic, the licensed end-of-chapter songs, Petri Alanko''s score and the live-action inserts form a single unmistakable signature.', NULL FROM subcriteria s JOIN dimensions d ON d.id = s.dimension_id WHERE d.rubric_version = '1.0' AND d.key = 'atmosphere' AND s.key = 'audiovisual_identity';
INSERT INTO subcriterion_scores (evaluation_id, subcriterion_id, score, rationale, platform_note) SELECT (SELECT e.id FROM evaluations e JOIN games g ON g.id = e.game_id WHERE g.slug = 'alan-wake-2' AND e.version_number = 1), s.id, 2, 'The Dark Place operates by stated rules the fiction obeys, and the wider Remedy continuity strengthens rather than clutters it.', NULL FROM subcriteria s JOIN dimensions d ON d.id = s.dimension_id WHERE d.rubric_version = '1.0' AND d.key = 'atmosphere' AND s.key = 'world_coherence';
INSERT INTO subcriterion_scores (evaluation_id, subcriterion_id, score, rationale, platform_note) SELECT (SELECT e.id FROM evaluations e JOIN games g ON g.id = e.game_id WHERE g.slug = 'alan-wake-2' AND e.version_number = 1), s.id, 2, 'The Oceanview Hotel musical sequence, the talk-show segments and the Watery caravan park are the kind of set pieces players describe to other people years later.', NULL FROM subcriteria s JOIN dimensions d ON d.id = s.dimension_id WHERE d.rubric_version = '1.0' AND d.key = 'atmosphere' AND s.key = 'memory_residue';
INSERT INTO subcriterion_scores (evaluation_id, subcriterion_id, score, rationale, platform_note) SELECT (SELECT e.id FROM evaluations e JOIN games g ON g.id = e.game_id WHERE g.slug = 'alan-wake-2' AND e.version_number = 1), s.id, 2, 'Authorship, control and the cost of shaping reality by telling stories about it are the explicit subject, not a reading imposed on it.', NULL FROM subcriteria s JOIN dimensions d ON d.id = s.dimension_id WHERE d.rubric_version = '1.0' AND d.key = 'thematic' AND s.key = 'thematic_clarity';
INSERT INTO subcriterion_scores (evaluation_id, subcriterion_id, score, rationale, platform_note) SELECT (SELECT e.id FROM evaluations e JOIN games g ON g.id = e.game_id WHERE g.slug = 'alan-wake-2' AND e.version_number = 1), s.id, 1.5, 'Saga''s family material lands genuinely, though the game''s formal cleverness sometimes holds the audience at a slight distance from its feeling.', NULL FROM subcriteria s JOIN dimensions d ON d.id = s.dimension_id WHERE d.rubric_version = '1.0' AND d.key = 'thematic' AND s.key = 'emotional_power';
INSERT INTO subcriterion_scores (evaluation_id, subcriterion_id, score, rationale, platform_note) SELECT (SELECT e.id FROM evaluations e JOIN games g ON g.id = e.game_id WHERE g.slug = 'alan-wake-2' AND e.version_number = 1), s.id, 2, 'Wake''s writing is the mechanism of the plot; his self-destruction and the manuscript''s power are the same fact expressed two ways.', NULL FROM subcriteria s JOIN dimensions d ON d.id = s.dimension_id WHERE d.rubric_version = '1.0' AND d.key = 'thematic' AND s.key = 'theme_character_integration';
INSERT INTO subcriterion_scores (evaluation_id, subcriterion_id, score, rationale, platform_note) SELECT (SELECT e.id FROM evaluations e JOIN games g ON g.id = e.game_id WHERE g.slug = 'alan-wake-2' AND e.version_number = 1), s.id, 2, 'It reaches for the horror of authorship and actually gives it substance — the loop, the doubles and the rewriting all argue the same idea.', NULL FROM subcriteria s JOIN dimensions d ON d.id = s.dimension_id WHERE d.rubric_version = '1.0' AND d.key = 'thematic' AND s.key = 'philosophical_weight';
INSERT INTO subcriterion_scores (evaluation_id, subcriterion_id, score, rationale, platform_note) SELECT (SELECT e.id FROM evaluations e JOIN games g ON g.id = e.game_id WHERE g.slug = 'alan-wake-2' AND e.version_number = 1), s.id, 1.5, 'The formal invention persists strongly in memory; the emotional residue is thinner than the intellectual one.', NULL FROM subcriteria s JOIN dimensions d ON d.id = s.dimension_id WHERE d.rubric_version = '1.0' AND d.key = 'thematic' AND s.key = 'lasting_impact';
INSERT INTO subcriterion_scores (evaluation_id, subcriterion_id, score, rationale, platform_note) SELECT (SELECT e.id FROM evaluations e JOIN games g ON g.id = e.game_id WHERE g.slug = 'alan-wake-2' AND e.version_number = 1), s.id, 2, 'The Writer''s Room literally makes editing the story into the level design: choosing a scene rewrites the space you then walk through.', NULL FROM subcriteria s JOIN dimensions d ON d.id = s.dimension_id WHERE d.rubric_version = '1.0' AND d.key = 'craft' AND s.key = 'mechanics_meaning';
INSERT INTO subcriterion_scores (evaluation_id, subcriterion_id, score, rationale, platform_note) SELECT (SELECT e.id FROM evaluations e JOIN games g ON g.id = e.game_id WHERE g.slug = 'alan-wake-2' AND e.version_number = 1), s.id, 2, 'Playing the second campaign systematically changes what earlier scenes meant, and the game is built to be re-read rather than merely replayed.', NULL FROM subcriteria s JOIN dimensions d ON d.id = s.dimension_id WHERE d.rubric_version = '1.0' AND d.key = 'craft' AND s.key = 'player_recontextualization';
INSERT INTO subcriterion_scores (evaluation_id, subcriterion_id, score, rationale, platform_note) SELECT (SELECT e.id FROM evaluations e JOIN games g ON g.id = e.game_id WHERE g.slug = 'alan-wake-2' AND e.version_number = 1), s.id, 2, 'The Case Board makes deduction a player action. Connections are drawn by you, so understanding arrives as something you did rather than something you were told.', NULL FROM subcriteria s JOIN dimensions d ON d.id = s.dimension_id WHERE d.rubric_version = '1.0' AND d.key = 'craft' AND s.key = 'interactive_revelation';
INSERT INTO subcriterion_scores (evaluation_id, subcriterion_id, score, rationale, platform_note) SELECT (SELECT e.id FROM evaluations e JOIN games g ON g.id = e.game_id WHERE g.slug = 'alan-wake-2' AND e.version_number = 1), s.id, 2, 'Converted to film, the central device collapses — the horror depends on the player being the one holding the pen and choosing the order.', NULL FROM subcriteria s JOIN dimensions d ON d.id = s.dimension_id WHERE d.rubric_version = '1.0' AND d.key = 'craft' AND s.key = 'medium_irreplaceability';
INSERT INTO subcriterion_scores (evaluation_id, subcriterion_id, score, rationale, platform_note) SELECT (SELECT e.id FROM evaluations e JOIN games g ON g.id = e.game_id WHERE g.slug = 'alan-wake-2' AND e.version_number = 1), s.id, 1.5, 'Player choice shapes sequence and interpretation rather than outcome; the plot itself is fixed, so agency is expressive rather than consequential.', NULL FROM subcriteria s JOIN dimensions d ON d.id = s.dimension_id WHERE d.rubric_version = '1.0' AND d.key = 'craft' AND s.key = 'meaningful_agency';
INSERT INTO profile_blocks (evaluation_id, block_type, item_order, text) VALUES ((SELECT e.id FROM evaluations e JOIN games g ON g.id = e.game_id WHERE g.slug = 'alan-wake-2' AND e.version_number = 1), 'great_fit', 1, 'You want a horror story that takes its own structure seriously and expects you to assemble it.');
INSERT INTO profile_blocks (evaluation_id, block_type, item_order, text) VALUES ((SELECT e.id FROM evaluations e JOIN games g ON g.id = e.game_id WHERE g.slug = 'alan-wake-2' AND e.version_number = 1), 'great_fit', 2, 'Place and atmosphere matter more to you than the volume of combat.');
INSERT INTO profile_blocks (evaluation_id, block_type, item_order, text) VALUES ((SELECT e.id FROM evaluations e JOIN games g ON g.id = e.game_id WHERE g.slug = 'alan-wake-2' AND e.version_number = 1), 'great_fit', 3, 'You enjoy investigation, environmental detail, and rereading a scene for what you missed.');
INSERT INTO profile_blocks (evaluation_id, block_type, item_order, text) VALUES ((SELECT e.id FROM evaluations e JOIN games g ON g.id = e.game_id WHERE g.slug = 'alan-wake-2' AND e.version_number = 1), 'great_fit', 4, 'You are comfortable with a deliberately slow, controlled tempo.');
INSERT INTO profile_blocks (evaluation_id, block_type, item_order, text) VALUES ((SELECT e.id FROM evaluations e JOIN games g ON g.id = e.game_id WHERE g.slug = 'alan-wake-2' AND e.version_number = 1), 'know_before', 1, 'Combat is infrequent, resource-limited and intentionally clumsy under pressure.');
INSERT INTO profile_blocks (evaluation_id, block_type, item_order, text) VALUES ((SELECT e.id FROM evaluations e JOIN games g ON g.id = e.game_id WHERE g.slug = 'alan-wake-2' AND e.version_number = 1), 'know_before', 2, 'You choose the order of the two campaigns, and that choice changes how the mystery unfolds for you.');
INSERT INTO profile_blocks (evaluation_id, block_type, item_order, text) VALUES ((SELECT e.id FROM evaluations e JOIN games g ON g.id = e.game_id WHERE g.slug = 'alan-wake-2' AND e.version_number = 1), 'know_before', 3, 'It is dense with text — manuscript pages, case files and case-board material you are expected to read.');
INSERT INTO profile_blocks (evaluation_id, block_type, item_order, text) VALUES ((SELECT e.id FROM evaluations e JOIN games g ON g.id = e.game_id WHERE g.slug = 'alan-wake-2' AND e.version_number = 1), 'know_before', 4, 'PC ray-traced settings are demanding; the console versions are the stable reference experience.');
INSERT INTO profile_blocks (evaluation_id, block_type, item_order, text) VALUES ((SELECT e.id FROM evaluations e JOIN games g ON g.id = e.game_id WHERE g.slug = 'alan-wake-2' AND e.version_number = 1), 'probably_not', 1, 'You want frequent, mechanically deep combat encounters.');
INSERT INTO profile_blocks (evaluation_id, block_type, item_order, text) VALUES ((SELECT e.id FROM evaluations e JOIN games g ON g.id = e.game_id WHERE g.slug = 'alan-wake-2' AND e.version_number = 1), 'probably_not', 2, 'You dislike ambiguity and want a plot that closes cleanly.');
INSERT INTO profile_blocks (evaluation_id, block_type, item_order, text) VALUES ((SELECT e.id FROM evaluations e JOIN games g ON g.id = e.game_id WHERE g.slug = 'alan-wake-2' AND e.version_number = 1), 'probably_not', 3, 'Long stretches of walking, reading and looking drain your interest.');
