INSERT INTO games (slug, canonical_title, summary, developer_text, publisher_text, first_release_date, release_status) VALUES ('returnal', 'Returnal', 'A third-person roguelike shooter in which a scout crash-lands on a hostile planet and finds that death returns her to the wreck of her own ship, with the world rearranged.', 'Housemarque', 'Sony Interactive Entertainment', '2021-04-30', 'released') ON CONFLICT (slug) DO NOTHING;
INSERT INTO game_platforms (game_id, platform_id) SELECT g.id, p.id FROM games g, platforms p WHERE g.slug = 'returnal' AND p.slug = 'ps5' ON CONFLICT DO NOTHING;
INSERT INTO game_platforms (game_id, platform_id) SELECT g.id, p.id FROM games g, platforms p WHERE g.slug = 'returnal' AND p.slug = 'pc' ON CONFLICT DO NOTHING;
INSERT INTO evaluations (game_id, rubric_version, version_number, edition_scope, mode_scope, platform_scope, build_or_patch_scope, current_state_cutoff_at, status, evidence_status, confidence, evidence_cutoff_at, release_context, one_line_experience, primary_pull, primary_risk, platform_warning, score_provenance, provenance_note, published_at, change_summary) SELECT id, '1.0', 1, 'Base game', 'Single-player campaign, excluding the co-op Tower of Sisyphus', ARRAY['PlayStation 5', 'PC'], 'Current retail build, including the suspend-cycle and Ascension updates', NULL, 'published', 'verified', 'high', '2026-08-06', 'Post-release', 'A bullet-hell shooter of extraordinary feel bound to a run structure that can take everything back, wrapped in a cryptic story about a woman who cannot stop arriving.', 'Combat and movement of near-reference quality — a speed, clarity and physical precision very few action games reach.', 'A single run can last hours and end with almost all of it gone. The structure asks for a kind of uninterrupted time many players cannot give it.', NULL, 'derived_pending_round_1_reconciliation', 'Scores derived from Rubric v1.0 pending reconciliation with the Calibration Round 1 report.', '2026-08-06'::timestamptz, NULL FROM games WHERE slug = 'returnal';
INSERT INTO subcriterion_scores (evaluation_id, subcriterion_id, score, rationale, platform_note) SELECT (SELECT e.id FROM evaluations e JOIN games g ON g.id = e.game_id WHERE g.slug = 'returnal' AND e.version_number = 1), s.id, 1.5, 'The premise lands instantly and is genuinely unsettling, but the game withholds so much so early that the hook is mood rather than stakes.', NULL FROM subcriteria s JOIN dimensions d ON d.id = s.dimension_id WHERE d.rubric_version = '1.0' AND d.key = 'story' AND s.key = 'story_hook';
INSERT INTO subcriterion_scores (evaluation_id, subcriterion_id, score, rationale, platform_note) SELECT (SELECT e.id FROM evaluations e JOIN games g ON g.id = e.game_id WHERE g.slug = 'returnal' AND e.version_number = 1), s.id, 1.5, 'Selene is a strong, well-performed presence and the house sequences give her real interiority, though she remains deliberately opaque for most of the runtime.', NULL FROM subcriteria s JOIN dimensions d ON d.id = s.dimension_id WHERE d.rubric_version = '1.0' AND d.key = 'story' AND s.key = 'character_investment';
INSERT INTO subcriterion_scores (evaluation_id, subcriterion_id, score, rationale, platform_note) SELECT (SELECT e.id FROM evaluations e JOIN games g ON g.id = e.game_id WHERE g.slug = 'returnal' AND e.version_number = 1), s.id, 1, 'The fiction sustains multiple mutually exclusive readings by design. Coherent as a psychological text, but the literal world rules are never settled.', NULL FROM subcriteria s JOIN dimensions d ON d.id = s.dimension_id WHERE d.rubric_version = '1.0' AND d.key = 'story' AND s.key = 'narrative_coherence';
INSERT INTO subcriterion_scores (evaluation_id, subcriterion_id, score, rationale, platform_note) SELECT (SELECT e.id FROM evaluations e JOIN games g ON g.id = e.game_id WHERE g.slug = 'returnal' AND e.version_number = 1), s.id, 1, 'Story arrives in fragments gated behind run progress, so long stretches deliver nothing new, and the payoff is contested rather than proportionate to the setup.', NULL FROM subcriteria s JOIN dimensions d ON d.id = s.dimension_id WHERE d.rubric_version = '1.0' AND d.key = 'story' AND s.key = 'narrative_momentum';
INSERT INTO subcriterion_scores (evaluation_id, subcriterion_id, score, rationale, platform_note) SELECT (SELECT e.id FROM evaluations e JOIN games g ON g.id = e.game_id WHERE g.slug = 'returnal' AND e.version_number = 1), s.id, 1.5, 'Scout logs, xeno-glyphs and the ruins carry most of the narrative weight and reward attention, though much of it stays allusive.', NULL FROM subcriteria s JOIN dimensions d ON d.id = s.dimension_id WHERE d.rubric_version = '1.0' AND d.key = 'story' AND s.key = 'world_lore_integration';
INSERT INTO subcriterion_scores (evaluation_id, subcriterion_id, score, rationale, platform_note) SELECT (SELECT e.id FROM evaluations e JOIN games g ON g.id = e.game_id WHERE g.slug = 'returnal' AND e.version_number = 1), s.id, 1.5, 'Sparse but well-judged. Jane Perry''s performance and the first-person house sequences are strong; there is simply not much dramatic material to execute.', NULL FROM subcriteria s JOIN dimensions d ON d.id = s.dimension_id WHERE d.rubric_version = '1.0' AND d.key = 'execution' AND s.key = 'dramatic_execution';
INSERT INTO subcriterion_scores (evaluation_id, subcriterion_id, score, rationale, platform_note) SELECT (SELECT e.id FROM evaluations e JOIN games g ON g.id = e.game_id WHERE g.slug = 'returnal' AND e.version_number = 1), s.id, 2, 'Aiming, dashing, projectile readability and the alt-fire cadence are close to flawless. Every input arrives exactly when and where it should.', NULL FROM subcriteria s JOIN dimensions d ON d.id = s.dimension_id WHERE d.rubric_version = '1.0' AND d.key = 'execution' AND s.key = 'gameplay_execution';
INSERT INTO subcriterion_scores (evaluation_id, subcriterion_id, score, rationale, platform_note) SELECT (SELECT e.id FROM evaluations e JOIN games g ON g.id = e.game_id WHERE g.slug = 'returnal' AND e.version_number = 1), s.id, 2, 'Locked 60fps on PS5 with no meaningful performance cost; the PC port is well-optimised and the DualSense implementation is a reference case.', NULL FROM subcriteria s JOIN dimensions d ON d.id = s.dimension_id WHERE d.rubric_version = '1.0' AND d.key = 'execution' AND s.key = 'technical_stability';
INSERT INTO subcriterion_scores (evaluation_id, subcriterion_id, score, rationale, platform_note) SELECT (SELECT e.id FROM evaluations e JOIN games g ON g.id = e.game_id WHERE g.slug = 'returnal' AND e.version_number = 1), s.id, 2, 'Audio, haptics, particle work and biome art operate as one system. The feedback loop between what you see, hear and feel in the controller is unusually tight.', NULL FROM subcriteria s JOIN dimensions d ON d.id = s.dimension_id WHERE d.rubric_version = '1.0' AND d.key = 'execution' AND s.key = 'production_cohesion';
INSERT INTO subcriterion_scores (evaluation_id, subcriterion_id, score, rationale, platform_note) SELECT (SELECT e.id FROM evaluations e JOIN games g ON g.id = e.game_id WHERE g.slug = 'returnal' AND e.version_number = 1), s.id, 1.5, 'Quality holds across all six biomes, though the later biomes reuse encounter grammar more heavily than the early ones.', NULL FROM subcriteria s JOIN dimensions d ON d.id = s.dimension_id WHERE d.rubric_version = '1.0' AND d.key = 'execution' AND s.key = 'consistency';
INSERT INTO subcriterion_scores (evaluation_id, subcriterion_id, score, rationale, platform_note) SELECT (SELECT e.id FROM evaluations e JOIN games g ON g.id = e.game_id WHERE g.slug = 'returnal' AND e.version_number = 1), s.id, 2, 'The run structure is not a genre habit here — the death loop is the story, and the mechanical reset and the narrative reset are the same event.', NULL FROM subcriteria s JOIN dimensions d ON d.id = s.dimension_id WHERE d.rubric_version = '1.0' AND d.key = 'structure' AND s.key = 'structural_intentionality';
INSERT INTO subcriterion_scores (evaluation_id, subcriterion_id, score, rationale, platform_note) SELECT (SELECT e.id FROM evaluations e JOIN games g ON g.id = e.game_id WHERE g.slug = 'returnal' AND e.version_number = 1), s.id, 1.5, 'Room-to-room readability is excellent and the map is clear, but recognising which procedural layout you are in takes practice.', NULL FROM subcriteria s JOIN dimensions d ON d.id = s.dimension_id WHERE d.rubric_version = '1.0' AND d.key = 'structure' AND s.key = 'navigation_legibility';
INSERT INTO subcriterion_scores (evaluation_id, subcriterion_id, score, rationale, platform_note) SELECT (SELECT e.id FROM evaluations e JOIN games g ON g.id = e.game_id WHERE g.slug = 'returnal' AND e.version_number = 1), s.id, 1, 'Early biomes are re-traversed many times, and after a failed late run the mandatory return through familiar rooms is the game''s most-cited friction.', NULL FROM subcriteria s JOIN dimensions d ON d.id = s.dimension_id WHERE d.rubric_version = '1.0' AND d.key = 'structure' AND s.key = 'repetition_control';
INSERT INTO subcriterion_scores (evaluation_id, subcriterion_id, score, rationale, platform_note) SELECT (SELECT e.id FROM evaluations e JOIN games g ON g.id = e.game_id WHERE g.slug = 'returnal' AND e.version_number = 1), s.id, 1.5, 'The interface is clean and information-dense. The suspend-cycle feature added later helps, but it is a single slot consumed on load rather than a save.', NULL FROM subcriteria s JOIN dimensions d ON d.id = s.dimension_id WHERE d.rubric_version = '1.0' AND d.key = 'structure' AND s.key = 'ux_friction';
INSERT INTO subcriterion_scores (evaluation_id, subcriterion_id, score, rationale, platform_note) SELECT (SELECT e.id FROM evaluations e JOIN games g ON g.id = e.game_id WHERE g.slug = 'returnal' AND e.version_number = 1), s.id, 1, 'Very little is padding by intent, yet the structure requires replaying cleared content as a matter of course, which produces the effect of padding regardless.', NULL FROM subcriteria s JOIN dimensions d ON d.id = s.dimension_id WHERE d.rubric_version = '1.0' AND d.key = 'structure' AND s.key = 'content_focus';
INSERT INTO subcriterion_scores (evaluation_id, subcriterion_id, score, rationale, platform_note) SELECT (SELECT e.id FROM evaluations e JOIN games g ON g.id = e.game_id WHERE g.slug = 'returnal' AND e.version_number = 1), s.id, 2, 'Survival in any given second is unambiguously a function of what the player does. There is almost no gap between intention and outcome.', NULL FROM subcriteria s JOIN dimensions d ON d.id = s.dimension_id WHERE d.rubric_version = '1.0' AND d.key = 'agency' AND s.key = 'moment_to_moment';
INSERT INTO subcriterion_scores (evaluation_id, subcriterion_id, score, rationale, platform_note) SELECT (SELECT e.id FROM evaluations e JOIN games g ON g.id = e.game_id WHERE g.slug = 'returnal' AND e.version_number = 1), s.id, 2, 'Ten weapon families with rolling traits, alt-fires, parasites, consumables and malignant items produce genuinely different builds run to run.', NULL FROM subcriteria s JOIN dimensions d ON d.id = s.dimension_id WHERE d.rubric_version = '1.0' AND d.key = 'agency' AND s.key = 'toolset_depth';
INSERT INTO subcriterion_scores (evaluation_id, subcriterion_id, score, rationale, platform_note) SELECT (SELECT e.id FROM evaluations e JOIN games g ON g.id = e.game_id WHERE g.slug = 'returnal' AND e.version_number = 1), s.id, 2, 'Weapon proficiency, artefacts and the adrenaline chain deliver reward on several timescales at once, from the individual room to the whole run.', NULL FROM subcriteria s JOIN dimensions d ON d.id = s.dimension_id WHERE d.rubric_version = '1.0' AND d.key = 'agency' AND s.key = 'reward_rhythm';
INSERT INTO subcriterion_scores (evaluation_id, subcriterion_id, score, rationale, platform_note) SELECT (SELECT e.id FROM evaluations e JOIN games g ON g.id = e.game_id WHERE g.slug = 'returnal' AND e.version_number = 1), s.id, 1.5, 'Damage is nearly always readable and avoidable — deaths feel earned. What is not proportionate is the cost: a fair death can still cost three hours.', NULL FROM subcriteria s JOIN dimensions d ON d.id = s.dimension_id WHERE d.rubric_version = '1.0' AND d.key = 'agency' AND s.key = 'failure_fairness';
INSERT INTO subcriterion_scores (evaluation_id, subcriterion_id, score, rationale, platform_note) SELECT (SELECT e.id FROM evaluations e JOIN games g ON g.id = e.game_id WHERE g.slug = 'returnal' AND e.version_number = 1), s.id, 2, 'Player capability is high enough to meet extreme pressure. The game is punishing, never helpless, and skill growth reliably converts into progress.', NULL FROM subcriteria s JOIN dimensions d ON d.id = s.dimension_id WHERE d.rubric_version = '1.0' AND d.key = 'agency' AND s.key = 'capability_balance';
INSERT INTO subcriterion_scores (evaluation_id, subcriterion_id, score, rationale, platform_note) SELECT (SELECT e.id FROM evaluations e JOIN games g ON g.id = e.game_id WHERE g.slug = 'returnal' AND e.version_number = 1), s.id, 1.5, 'The loop and tone establish quickly, though the first two hours give the player very few tools and read as harder than the game later is.', NULL FROM subcriteria s JOIN dimensions d ON d.id = s.dimension_id WHERE d.rubric_version = '1.0' AND d.key = 'pacing' AND s.key = 'opening_effectiveness';
INSERT INTO subcriterion_scores (evaluation_id, subcriterion_id, score, rationale, platform_note) SELECT (SELECT e.id FROM evaluations e JOIN games g ON g.id = e.game_id WHERE g.slug = 'returnal' AND e.version_number = 1), s.id, 1, 'Momentum is repeatedly reset by design. Progress is real across runs, but a lost run returns the player to material already mastered.', NULL FROM subcriteria s JOIN dimensions d ON d.id = s.dimension_id WHERE d.rubric_version = '1.0' AND d.key = 'pacing' AND s.key = 'momentum_maintenance';
INSERT INTO subcriterion_scores (evaluation_id, subcriterion_id, score, rationale, platform_note) SELECT (SELECT e.id FROM evaluations e JOIN games g ON g.id = e.game_id WHERE g.slug = 'returnal' AND e.version_number = 1), s.id, 1.5, 'The content justifies a long engagement for a player who bonds with the loop; the same content does not justify the hours spent re-clearing it for a player who does not.', NULL FROM subcriteria s JOIN dimensions d ON d.id = s.dimension_id WHERE d.rubric_version = '1.0' AND d.key = 'pacing' AND s.key = 'runtime_justification';
INSERT INTO subcriterion_scores (evaluation_id, subcriterion_id, score, rationale, platform_note) SELECT (SELECT e.id FROM evaluations e JOIN games g ON g.id = e.game_id WHERE g.slug = 'returnal' AND e.version_number = 1), s.id, 0.5, 'The game''s weakest point. A meaningful run can exceed three hours with no save, and the later suspend feature is one slot, deleted on load. The unit of progress does not fit most people''s lives.', NULL FROM subcriteria s JOIN dimensions d ON d.id = s.dimension_id WHERE d.rubric_version = '1.0' AND d.key = 'pacing' AND s.key = 'session_rhythm';
INSERT INTO subcriterion_scores (evaluation_id, subcriterion_id, score, rationale, platform_note) SELECT (SELECT e.id FROM evaluations e JOIN games g ON g.id = e.game_id WHERE g.slug = 'returnal' AND e.version_number = 1), s.id, 1.5, 'Almost no downtime within a run — the density inside a session is high, even though the density across the whole experience is diluted by repetition.', NULL FROM subcriteria s JOIN dimensions d ON d.id = s.dimension_id WHERE d.rubric_version = '1.0' AND d.key = 'pacing' AND s.key = 'content_density';
INSERT INTO subcriterion_scores (evaluation_id, subcriterion_id, score, rationale, platform_note) SELECT (SELECT e.id FROM evaluations e JOIN games g ON g.id = e.game_id WHERE g.slug = 'returnal' AND e.version_number = 1), s.id, 2, 'The six biomes are sharply distinct in silhouette, palette and sound, and Atropos coheres as one hostile planet rather than six themed levels.', NULL FROM subcriteria s JOIN dimensions d ON d.id = s.dimension_id WHERE d.rubric_version = '1.0' AND d.key = 'atmosphere' AND s.key = 'sense_of_place';
INSERT INTO subcriterion_scores (evaluation_id, subcriterion_id, score, rationale, platform_note) SELECT (SELECT e.id FROM evaluations e JOIN games g ON g.id = e.game_id WHERE g.slug = 'returnal' AND e.version_number = 1), s.id, 2, 'Sustained oppressive dread that never lets up, held together by an alien sound design that stays uncomfortable for the entire runtime.', NULL FROM subcriteria s JOIN dimensions d ON d.id = s.dimension_id WHERE d.rubric_version = '1.0' AND d.key = 'atmosphere' AND s.key = 'mood_strength';
INSERT INTO subcriterion_scores (evaluation_id, subcriterion_id, score, rationale, platform_note) SELECT (SELECT e.id FROM evaluations e JOIN games g ON g.id = e.game_id WHERE g.slug = 'returnal' AND e.version_number = 1), s.id, 2, 'Bogdan Chyzhevskyi''s score, the bullet-pattern light show and the haptic layer create an identity nothing else looks or feels like.', NULL FROM subcriteria s JOIN dimensions d ON d.id = s.dimension_id WHERE d.rubric_version = '1.0' AND d.key = 'atmosphere' AND s.key = 'audiovisual_identity';
INSERT INTO subcriterion_scores (evaluation_id, subcriterion_id, score, rationale, platform_note) SELECT (SELECT e.id FROM evaluations e JOIN games g ON g.id = e.game_id WHERE g.slug = 'returnal' AND e.version_number = 1), s.id, 1.5, 'The xeno-archaeology implies a real culture and history, but the deliberate ambiguity stops the world''s rules from ever fully settling.', NULL FROM subcriteria s JOIN dimensions d ON d.id = s.dimension_id WHERE d.rubric_version = '1.0' AND d.key = 'atmosphere' AND s.key = 'world_coherence';
INSERT INTO subcriterion_scores (evaluation_id, subcriterion_id, score, rationale, platform_note) SELECT (SELECT e.id FROM evaluations e JOIN games g ON g.id = e.game_id WHERE g.slug = 'returnal' AND e.version_number = 1), s.id, 1.5, 'The house sequences and the sound of the Severed are highly distinctive; the procedural rooms themselves blur together in memory.', NULL FROM subcriteria s JOIN dimensions d ON d.id = s.dimension_id WHERE d.rubric_version = '1.0' AND d.key = 'atmosphere' AND s.key = 'memory_residue';
INSERT INTO subcriterion_scores (evaluation_id, subcriterion_id, score, rationale, platform_note) SELECT (SELECT e.id FROM evaluations e JOIN games g ON g.id = e.game_id WHERE g.slug = 'returnal' AND e.version_number = 1), s.id, 1.5, 'Grief, compulsion and the refusal to accept an outcome are clearly the subject, though the game keeps its reading deliberately unresolved.', NULL FROM subcriteria s JOIN dimensions d ON d.id = s.dimension_id WHERE d.rubric_version = '1.0' AND d.key = 'thematic' AND s.key = 'thematic_clarity';
INSERT INTO subcriterion_scores (evaluation_id, subcriterion_id, score, rationale, platform_note) SELECT (SELECT e.id FROM evaluations e JOIN games g ON g.id = e.game_id WHERE g.slug = 'returnal' AND e.version_number = 1), s.id, 1.5, 'The house sequences are genuinely affecting and land harder for being rationed. The material around them is more atmospheric than emotional.', NULL FROM subcriteria s JOIN dimensions d ON d.id = s.dimension_id WHERE d.rubric_version = '1.0' AND d.key = 'thematic' AND s.key = 'emotional_power';
INSERT INTO subcriterion_scores (evaluation_id, subcriterion_id, score, rationale, platform_note) SELECT (SELECT e.id FROM evaluations e JOIN games g ON g.id = e.game_id WHERE g.slug = 'returnal' AND e.version_number = 1), s.id, 1.5, 'Selene''s inability to stop returning is both the mechanic and the psychology, though the connective tissue between them is left to the player to build.', NULL FROM subcriteria s JOIN dimensions d ON d.id = s.dimension_id WHERE d.rubric_version = '1.0' AND d.key = 'thematic' AND s.key = 'theme_character_integration';
INSERT INTO subcriterion_scores (evaluation_id, subcriterion_id, score, rationale, platform_note) SELECT (SELECT e.id FROM evaluations e JOIN games g ON g.id = e.game_id WHERE g.slug = 'returnal' AND e.version_number = 1), s.id, 1.5, 'It reaches seriously for guilt, denial and the myth of Sisyphus and gives them real substance, without arriving anywhere conclusive.', NULL FROM subcriteria s JOIN dimensions d ON d.id = s.dimension_id WHERE d.rubric_version = '1.0' AND d.key = 'thematic' AND s.key = 'philosophical_weight';
INSERT INTO subcriterion_scores (evaluation_id, subcriterion_id, score, rationale, platform_note) SELECT (SELECT e.id FROM evaluations e JOIN games g ON g.id = e.game_id WHERE g.slug = 'returnal' AND e.version_number = 1), s.id, 1.5, 'The ending has sustained years of argument, which is itself evidence of residue, though many players remember the feel of playing it over what it meant.', NULL FROM subcriteria s JOIN dimensions d ON d.id = s.dimension_id WHERE d.rubric_version = '1.0' AND d.key = 'thematic' AND s.key = 'lasting_impact';
INSERT INTO subcriterion_scores (evaluation_id, subcriterion_id, score, rationale, platform_note) SELECT (SELECT e.id FROM evaluations e JOIN games g ON g.id = e.game_id WHERE g.slug = 'returnal' AND e.version_number = 1), s.id, 2, 'The death loop is not a metaphor bolted to a roguelike; the compulsion to run again is the game''s argument about its protagonist, enacted by the player.', NULL FROM subcriteria s JOIN dimensions d ON d.id = s.dimension_id WHERE d.rubric_version = '1.0' AND d.key = 'craft' AND s.key = 'mechanics_meaning';
INSERT INTO subcriterion_scores (evaluation_id, subcriterion_id, score, rationale, platform_note) SELECT (SELECT e.id FROM evaluations e JOIN games g ON g.id = e.game_id WHERE g.slug = 'returnal' AND e.version_number = 1), s.id, 1.5, 'Act 3 and the second ending materially change what the earlier runs meant, though the reframing is optional and easily missed.', NULL FROM subcriteria s JOIN dimensions d ON d.id = s.dimension_id WHERE d.rubric_version = '1.0' AND d.key = 'craft' AND s.key = 'player_recontextualization';
INSERT INTO subcriterion_scores (evaluation_id, subcriterion_id, score, rationale, platform_note) SELECT (SELECT e.id FROM evaluations e JOIN games g ON g.id = e.game_id WHERE g.slug = 'returnal' AND e.version_number = 1), s.id, 1.5, 'Understanding Atropos is a function of exploring it, and mastery is learned only by doing, though most explicit lore still arrives as text to read.', NULL FROM subcriteria s JOIN dimensions d ON d.id = s.dimension_id WHERE d.rubric_version = '1.0' AND d.key = 'craft' AND s.key = 'interactive_revelation';
INSERT INTO subcriterion_scores (evaluation_id, subcriterion_id, score, rationale, platform_note) SELECT (SELECT e.id FROM evaluations e JOIN games g ON g.id = e.game_id WHERE g.slug = 'returnal' AND e.version_number = 1), s.id, 2, 'Told passively, the central experience disappears entirely — the point is that you, personally, lost the progress and chose to start again.', NULL FROM subcriteria s JOIN dimensions d ON d.id = s.dimension_id WHERE d.rubric_version = '1.0' AND d.key = 'craft' AND s.key = 'medium_irreplaceability';
INSERT INTO subcriterion_scores (evaluation_id, subcriterion_id, score, rationale, platform_note) SELECT (SELECT e.id FROM evaluations e JOIN games g ON g.id = e.game_id WHERE g.slug = 'returnal' AND e.version_number = 1), s.id, 1.5, 'Build and route choices carry genuine consequence within a run, but they do not alter the story, so the meaning is felt rather than authored.', NULL FROM subcriteria s JOIN dimensions d ON d.id = s.dimension_id WHERE d.rubric_version = '1.0' AND d.key = 'craft' AND s.key = 'meaningful_agency';
INSERT INTO profile_blocks (evaluation_id, block_type, item_order, text) VALUES ((SELECT e.id FROM evaluations e JOIN games g ON g.id = e.game_id WHERE g.slug = 'returnal' AND e.version_number = 1), 'great_fit', 1, 'You want combat that rewards practice, and you will keep playing to get better at it.');
INSERT INTO profile_blocks (evaluation_id, block_type, item_order, text) VALUES ((SELECT e.id FROM evaluations e JOIN games g ON g.id = e.game_id WHERE g.slug = 'returnal' AND e.version_number = 1), 'great_fit', 2, 'You can give the game long uninterrupted sessions.');
INSERT INTO profile_blocks (evaluation_id, block_type, item_order, text) VALUES ((SELECT e.id FROM evaluations e JOIN games g ON g.id = e.game_id WHERE g.slug = 'returnal' AND e.version_number = 1), 'great_fit', 3, 'You enjoy building around whatever weapons and traits a run happens to give you.');
INSERT INTO profile_blocks (evaluation_id, block_type, item_order, text) VALUES ((SELECT e.id FROM evaluations e JOIN games g ON g.id = e.game_id WHERE g.slug = 'returnal' AND e.version_number = 1), 'great_fit', 4, 'You are comfortable with a story that stays deliberately unresolved.');
INSERT INTO profile_blocks (evaluation_id, block_type, item_order, text) VALUES ((SELECT e.id FROM evaluations e JOIN games g ON g.id = e.game_id WHERE g.slug = 'returnal' AND e.version_number = 1), 'know_before', 1, 'A full run can exceed three hours, and the suspend feature is a single slot that is consumed when you resume.');
INSERT INTO profile_blocks (evaluation_id, block_type, item_order, text) VALUES ((SELECT e.id FROM evaluations e JOIN games g ON g.id = e.game_id WHERE g.slug = 'returnal' AND e.version_number = 1), 'know_before', 2, 'Dying returns you to the start with your permanent upgrades but not your build.');
INSERT INTO profile_blocks (evaluation_id, block_type, item_order, text) VALUES ((SELECT e.id FROM evaluations e JOIN games g ON g.id = e.game_id WHERE g.slug = 'returnal' AND e.version_number = 1), 'know_before', 3, 'The early biomes are re-traversed many times over the course of the game.');
INSERT INTO profile_blocks (evaluation_id, block_type, item_order, text) VALUES ((SELECT e.id FROM evaluations e JOIN games g ON g.id = e.game_id WHERE g.slug = 'returnal' AND e.version_number = 1), 'know_before', 4, 'Story is delivered in fragments gated behind progress, not in a continuous thread.');
INSERT INTO profile_blocks (evaluation_id, block_type, item_order, text) VALUES ((SELECT e.id FROM evaluations e JOIN games g ON g.id = e.game_id WHERE g.slug = 'returnal' AND e.version_number = 1), 'probably_not', 1, 'You dislike repeated run failure and replaying sections you have already cleared.');
INSERT INTO profile_blocks (evaluation_id, block_type, item_order, text) VALUES ((SELECT e.id FROM evaluations e JOIN games g ON g.id = e.game_id WHERE g.slug = 'returnal' AND e.version_number = 1), 'probably_not', 2, 'You mostly play in short sessions and need to stop whenever you like.');
INSERT INTO profile_blocks (evaluation_id, block_type, item_order, text) VALUES ((SELECT e.id FROM evaluations e JOIN games g ON g.id = e.game_id WHERE g.slug = 'returnal' AND e.version_number = 1), 'probably_not', 3, 'You want a narrative that explains itself.');
