INSERT INTO games (slug, canonical_title, summary, developer_text, publisher_text, first_release_date, release_status) VALUES ('redfall', 'Redfall', 'An open-world first-person shooter set in a Massachusetts island town cut off from the mainland by vampires, playable solo or in co-op with one of four characters.', 'Arkane Austin', 'Bethesda Softworks', '2023-05-02', 'released') ON CONFLICT (slug) DO NOTHING;
INSERT INTO game_platforms (game_id, platform_id) SELECT g.id, p.id FROM games g, platforms p WHERE g.slug = 'redfall' AND p.slug = 'xbox-series' ON CONFLICT DO NOTHING;
INSERT INTO game_platforms (game_id, platform_id) SELECT g.id, p.id FROM games g, platforms p WHERE g.slug = 'redfall' AND p.slug = 'pc' ON CONFLICT DO NOTHING;
INSERT INTO evaluations (game_id, rubric_version, version_number, edition_scope, mode_scope, platform_scope, build_or_patch_scope, current_state_cutoff_at, status, evidence_status, confidence, evidence_cutoff_at, release_context, one_line_experience, primary_pull, primary_risk, platform_warning, score_provenance, provenance_note, published_at, change_summary) SELECT id, '1.0', 1, 'Base game', 'Campaign, solo or co-op', ARRAY['Xbox Series X|S', 'PC'], 'Game Update 4 — the final update', '2026-08-06', 'published', 'provisional', 'medium', '2026-08-06', 'Post-release, final build', 'An open-world vampire shooter whose town and toolkit are more interesting than anything it asks you to do in them.', 'A visually distinctive vampire-town premise with some enjoyable weapons and abilities, particularly in cooperative play.', 'The world, shooting, AI, mission structure and systemic interactions rarely generate enough depth or surprise to sustain the premise.', NULL, 'calibration_round_2', NULL, '2026-08-06'::timestamptz, 'Profile scores the final Game Update 4 build, not the 2023 launch build. Confidence is held at Medium because most full critical reviews assessed the earlier state.' FROM games WHERE slug = 'redfall';
INSERT INTO subcriterion_scores (evaluation_id, subcriterion_id, score, rationale, platform_note) SELECT (SELECT e.id FROM evaluations e JOIN games g ON g.id = e.game_id WHERE g.slug = 'redfall' AND e.version_number = 1), s.id, 1, 'A vampire-besieged island town is a serviceable premise, but the game states it rather than dramatising it, and the stakes never sharpen past the opening.', NULL FROM subcriteria s JOIN dimensions d ON d.id = s.dimension_id WHERE d.rubric_version = '1.0' AND d.key = 'story' AND s.key = 'story_hook';
INSERT INTO subcriterion_scores (evaluation_id, subcriterion_id, score, rationale, platform_note) SELECT (SELECT e.id FROM evaluations e JOIN games g ON g.id = e.game_id WHERE g.slug = 'redfall' AND e.version_number = 1), s.id, 1, 'The four heroes have distinct silhouettes and abilities but almost no arc; they comment on events rather than being changed by them.', NULL FROM subcriteria s JOIN dimensions d ON d.id = s.dimension_id WHERE d.rubric_version = '1.0' AND d.key = 'story' AND s.key = 'character_investment';
INSERT INTO subcriterion_scores (evaluation_id, subcriterion_id, score, rationale, platform_note) SELECT (SELECT e.id FROM evaluations e JOIN games g ON g.id = e.game_id WHERE g.slug = 'redfall' AND e.version_number = 1), s.id, 1, 'The plot holds together at a basic level, though the relationship between the cult, the vampire gods and the town''s collapse stays underspecified.', NULL FROM subcriteria s JOIN dimensions d ON d.id = s.dimension_id WHERE d.rubric_version = '1.0' AND d.key = 'story' AND s.key = 'narrative_coherence';
INSERT INTO subcriterion_scores (evaluation_id, subcriterion_id, score, rationale, platform_note) SELECT (SELECT e.id FROM evaluations e JOIN games g ON g.id = e.game_id WHERE g.slug = 'redfall' AND e.version_number = 1), s.id, 0.5, 'Story is delivered mostly through static mission briefings and text; long stretches pass with no development, and the finale arrives without adequate build.', NULL FROM subcriteria s JOIN dimensions d ON d.id = s.dimension_id WHERE d.rubric_version = '1.0' AND d.key = 'story' AND s.key = 'narrative_momentum';
INSERT INTO subcriterion_scores (evaluation_id, subcriterion_id, score, rationale, platform_note) SELECT (SELECT e.id FROM evaluations e JOIN games g ON g.id = e.game_id WHERE g.slug = 'redfall' AND e.version_number = 1), s.id, 1, 'Environmental storytelling in the abandoned houses is the strongest narrative material in the game, but it sits beside the plot rather than feeding it.', NULL FROM subcriteria s JOIN dimensions d ON d.id = s.dimension_id WHERE d.rubric_version = '1.0' AND d.key = 'story' AND s.key = 'world_lore_integration';
INSERT INTO subcriterion_scores (evaluation_id, subcriterion_id, score, rationale, platform_note) SELECT (SELECT e.id FROM evaluations e JOIN games g ON g.id = e.game_id WHERE g.slug = 'redfall' AND e.version_number = 1), s.id, 1, 'Voice work is competent and occasional lines land, but scene construction is minimal and most exposition is delivered standing still in a safe house.', NULL FROM subcriteria s JOIN dimensions d ON d.id = s.dimension_id WHERE d.rubric_version = '1.0' AND d.key = 'execution' AND s.key = 'dramatic_execution';
INSERT INTO subcriterion_scores (evaluation_id, subcriterion_id, score, rationale, platform_note) SELECT (SELECT e.id FROM evaluations e JOIN games g ON g.id = e.game_id WHERE g.slug = 'redfall' AND e.version_number = 1), s.id, 1.5, 'Gunplay itself is reasonable and the ability sets are readable. Enemy AI, pathing and reaction behaviour are the clearest implementation weakness.', NULL FROM subcriteria s JOIN dimensions d ON d.id = s.dimension_id WHERE d.rubric_version = '1.0' AND d.key = 'execution' AND s.key = 'gameplay_execution';
INSERT INTO subcriterion_scores (evaluation_id, subcriterion_id, score, rationale, platform_note) SELECT (SELECT e.id FROM evaluations e JOIN games g ON g.id = e.game_id WHERE g.slug = 'redfall' AND e.version_number = 1), s.id, 1, 'Update 4 resolved the worst of the launch state and added a 60fps performance mode, but pop-in, traversal hitching and animation faults remain routine.', 'Assessed on Xbox Series X|S and PC at the Game Update 4 build.' FROM subcriteria s JOIN dimensions d ON d.id = s.dimension_id WHERE d.rubric_version = '1.0' AND d.key = 'execution' AND s.key = 'technical_stability';
INSERT INTO subcriterion_scores (evaluation_id, subcriterion_id, score, rationale, platform_note) SELECT (SELECT e.id FROM evaluations e JOIN games g ON g.id = e.game_id WHERE g.slug = 'redfall' AND e.version_number = 1), s.id, 1, 'Art direction and systems design point in different directions: the town is dressed as an immersive sim while the mission and loot layer is a live-service shooter.', NULL FROM subcriteria s JOIN dimensions d ON d.id = s.dimension_id WHERE d.rubric_version = '1.0' AND d.key = 'execution' AND s.key = 'production_cohesion';
INSERT INTO subcriterion_scores (evaluation_id, subcriterion_id, score, rationale, platform_note) SELECT (SELECT e.id FROM evaluations e JOIN games g ON g.id = e.game_id WHERE g.slug = 'redfall' AND e.version_number = 1), s.id, 1, 'Quality is uniformly mid rather than uneven — the second district repeats the structure of the first without improving on it.', NULL FROM subcriteria s JOIN dimensions d ON d.id = s.dimension_id WHERE d.rubric_version = '1.0' AND d.key = 'execution' AND s.key = 'consistency';
INSERT INTO subcriterion_scores (evaluation_id, subcriterion_id, score, rationale, platform_note) SELECT (SELECT e.id FROM evaluations e JOIN games g ON g.id = e.game_id WHERE g.slug = 'redfall' AND e.version_number = 1), s.id, 1, 'The open-world-plus-safehouse form is a recognisable shape, but it serves neither the co-op shooter nor the immersive-sim instincts the game keeps gesturing at.', NULL FROM subcriteria s JOIN dimensions d ON d.id = s.dimension_id WHERE d.rubric_version = '1.0' AND d.key = 'structure' AND s.key = 'structural_intentionality';
INSERT INTO subcriterion_scores (evaluation_id, subcriterion_id, score, rationale, platform_note) SELECT (SELECT e.id FROM evaluations e JOIN games g ON g.id = e.game_id WHERE g.slug = 'redfall' AND e.version_number = 1), s.id, 1, 'The map and objective markers work as intended; the town is legible enough to cross, but rarely gives a reason to prefer one route over another.', NULL FROM subcriteria s JOIN dimensions d ON d.id = s.dimension_id WHERE d.rubric_version = '1.0' AND d.key = 'structure' AND s.key = 'navigation_legibility';
INSERT INTO subcriterion_scores (evaluation_id, subcriterion_id, score, rationale, platform_note) SELECT (SELECT e.id FROM evaluations e JOIN games g ON g.id = e.game_id WHERE g.slug = 'redfall' AND e.version_number = 1), s.id, 0.5, 'Nests and Neighborhood objectives recycle a very small set of layouts and goals, and the game asks the player to run them repeatedly across both districts.', NULL FROM subcriteria s JOIN dimensions d ON d.id = s.dimension_id WHERE d.rubric_version = '1.0' AND d.key = 'structure' AND s.key = 'repetition_control';
INSERT INTO subcriterion_scores (evaluation_id, subcriterion_id, score, rationale, platform_note) SELECT (SELECT e.id FROM evaluations e JOIN games g ON g.id = e.game_id WHERE g.slug = 'redfall' AND e.version_number = 1), s.id, 1, 'Menus, inventory and the safe-house loop are functional. Update 4 added offline play and pausing, removing the most severe friction the game shipped with.', NULL FROM subcriteria s JOIN dimensions d ON d.id = s.dimension_id WHERE d.rubric_version = '1.0' AND d.key = 'structure' AND s.key = 'ux_friction';
INSERT INTO subcriterion_scores (evaluation_id, subcriterion_id, score, rationale, platform_note) SELECT (SELECT e.id FROM evaluations e JOIN games g ON g.id = e.game_id WHERE g.slug = 'redfall' AND e.version_number = 1), s.id, 1, 'A large share of the map is populated with activities that exist to fill it, and clearing them changes little about the experience.', NULL FROM subcriteria s JOIN dimensions d ON d.id = s.dimension_id WHERE d.rubric_version = '1.0' AND d.key = 'structure' AND s.key = 'content_focus';
INSERT INTO subcriterion_scores (evaluation_id, subcriterion_id, score, rationale, platform_note) SELECT (SELECT e.id FROM evaluations e JOIN games g ON g.id = e.game_id WHERE g.slug = 'redfall' AND e.version_number = 1), s.id, 1.5, 'Shooting, staking and ability use are direct and responsive; the immediate act of fighting is the most competent thing the game does.', NULL FROM subcriteria s JOIN dimensions d ON d.id = s.dimension_id WHERE d.rubric_version = '1.0' AND d.key = 'agency' AND s.key = 'moment_to_moment';
INSERT INTO subcriterion_scores (evaluation_id, subcriterion_id, score, rationale, platform_note) SELECT (SELECT e.id FROM evaluations e JOIN games g ON g.id = e.game_id WHERE g.slug = 'redfall' AND e.version_number = 1), s.id, 1.5, 'Character abilities, UV weapons and stake launchers offer real variety, and the co-op combinations are where the design comes closest to working.', NULL FROM subcriteria s JOIN dimensions d ON d.id = s.dimension_id WHERE d.rubric_version = '1.0' AND d.key = 'agency' AND s.key = 'toolset_depth';
INSERT INTO subcriterion_scores (evaluation_id, subcriterion_id, score, rationale, platform_note) SELECT (SELECT e.id FROM evaluations e JOIN games g ON g.id = e.game_id WHERE g.slug = 'redfall' AND e.version_number = 1), s.id, 1, 'Loot arrives steadily but is mostly incremental rarity; few drops change how a character is played.', NULL FROM subcriteria s JOIN dimensions d ON d.id = s.dimension_id WHERE d.rubric_version = '1.0' AND d.key = 'agency' AND s.key = 'reward_rhythm';
INSERT INTO subcriterion_scores (evaluation_id, subcriterion_id, score, rationale, platform_note) SELECT (SELECT e.id FROM evaluations e JOIN games g ON g.id = e.game_id WHERE g.slug = 'redfall' AND e.version_number = 1), s.id, 1, 'Failure is readable and cheap, though this is less a design achievement than a consequence of encounters that rarely threaten a prepared player.', NULL FROM subcriteria s JOIN dimensions d ON d.id = s.dimension_id WHERE d.rubric_version = '1.0' AND d.key = 'agency' AND s.key = 'failure_fairness';
INSERT INTO subcriterion_scores (evaluation_id, subcriterion_id, score, rationale, platform_note) SELECT (SELECT e.id FROM evaluations e JOIN games g ON g.id = e.game_id WHERE g.slug = 'redfall' AND e.version_number = 1), s.id, 0.5, 'The relationship between capability and pressure collapses: enemy AI is passive enough that player power is rarely tested, so the loop stops generating tension well before the campaign ends.', NULL FROM subcriteria s JOIN dimensions d ON d.id = s.dimension_id WHERE d.rubric_version = '1.0' AND d.key = 'agency' AND s.key = 'capability_balance';
INSERT INTO subcriterion_scores (evaluation_id, subcriterion_id, score, rationale, platform_note) SELECT (SELECT e.id FROM evaluations e JOIN games g ON g.id = e.game_id WHERE g.slug = 'redfall' AND e.version_number = 1), s.id, 1, 'The opening establishes the premise and the loop efficiently, but shows the player almost everything the game will do within the first two hours.', NULL FROM subcriteria s JOIN dimensions d ON d.id = s.dimension_id WHERE d.rubric_version = '1.0' AND d.key = 'pacing' AND s.key = 'opening_effectiveness';
INSERT INTO subcriterion_scores (evaluation_id, subcriterion_id, score, rationale, platform_note) SELECT (SELECT e.id FROM evaluations e JOIN games g ON g.id = e.game_id WHERE g.slug = 'redfall' AND e.version_number = 1), s.id, 1, 'The campaign advances but does not escalate; the second district restates the first at a higher enemy level.', NULL FROM subcriteria s JOIN dimensions d ON d.id = s.dimension_id WHERE d.rubric_version = '1.0' AND d.key = 'pacing' AND s.key = 'momentum_maintenance';
INSERT INTO subcriterion_scores (evaluation_id, subcriterion_id, score, rationale, platform_note) SELECT (SELECT e.id FROM evaluations e JOIN games g ON g.id = e.game_id WHERE g.slug = 'redfall' AND e.version_number = 1), s.id, 0.5, 'Roughly 15–20 hours of content built from perhaps four hours of distinct ideas. The runtime is reached through repetition rather than development.', NULL FROM subcriteria s JOIN dimensions d ON d.id = s.dimension_id WHERE d.rubric_version = '1.0' AND d.key = 'pacing' AND s.key = 'runtime_justification';
INSERT INTO subcriterion_scores (evaluation_id, subcriterion_id, score, rationale, platform_note) SELECT (SELECT e.id FROM evaluations e JOIN games g ON g.id = e.game_id WHERE g.slug = 'redfall' AND e.version_number = 1), s.id, 1, 'Missions and Neighborhood objectives make clean, legible stopping points, and Update 4''s pause and offline support finally made short sessions practical.', NULL FROM subcriteria s JOIN dimensions d ON d.id = s.dimension_id WHERE d.rubric_version = '1.0' AND d.key = 'pacing' AND s.key = 'session_rhythm';
INSERT INTO subcriterion_scores (evaluation_id, subcriterion_id, score, rationale, platform_note) SELECT (SELECT e.id FROM evaluations e JOIN games g ON g.id = e.game_id WHERE g.slug = 'redfall' AND e.version_number = 1), s.id, 1, 'Meaningful encounters are separated by long, quiet traversal across a town with little to find between objectives.', NULL FROM subcriteria s JOIN dimensions d ON d.id = s.dimension_id WHERE d.rubric_version = '1.0' AND d.key = 'pacing' AND s.key = 'content_density';
INSERT INTO subcriterion_scores (evaluation_id, subcriterion_id, score, rationale, platform_note) SELECT (SELECT e.id FROM evaluations e JOIN games g ON g.id = e.game_id WHERE g.slug = 'redfall' AND e.version_number = 1), s.id, 1.5, 'Redfall itself is the game''s real achievement — a specific New England town, convincingly emptied, with genuinely eerie interiors.', NULL FROM subcriteria s JOIN dimensions d ON d.id = s.dimension_id WHERE d.rubric_version = '1.0' AND d.key = 'atmosphere' AND s.key = 'sense_of_place';
INSERT INTO subcriterion_scores (evaluation_id, subcriterion_id, score, rationale, platform_note) SELECT (SELECT e.id FROM evaluations e JOIN games g ON g.id = e.game_id WHERE g.slug = 'redfall' AND e.version_number = 1), s.id, 1, 'The dread the town establishes is undercut constantly by loot markers, respawning enemies and a mission layer that treats the setting as a playground.', NULL FROM subcriteria s JOIN dimensions d ON d.id = s.dimension_id WHERE d.rubric_version = '1.0' AND d.key = 'atmosphere' AND s.key = 'mood_strength';
INSERT INTO subcriterion_scores (evaluation_id, subcriterion_id, score, rationale, platform_note) SELECT (SELECT e.id FROM evaluations e JOIN games g ON g.id = e.game_id WHERE g.slug = 'redfall' AND e.version_number = 1), s.id, 1.5, 'The blood-red sky, the frozen sea and the psychic vampire silhouettes are strong, memorable images that most of the game does not live up to.', NULL FROM subcriteria s JOIN dimensions d ON d.id = s.dimension_id WHERE d.rubric_version = '1.0' AND d.key = 'atmosphere' AND s.key = 'audiovisual_identity';
INSERT INTO subcriterion_scores (evaluation_id, subcriterion_id, score, rationale, platform_note) SELECT (SELECT e.id FROM evaluations e JOIN games g ON g.id = e.game_id WHERE g.slug = 'redfall' AND e.version_number = 1), s.id, 1, 'The rules of the vampire outbreak are established but applied loosely, and the town''s internal logic bends to accommodate the shooter systems.', NULL FROM subcriteria s JOIN dimensions d ON d.id = s.dimension_id WHERE d.rubric_version = '1.0' AND d.key = 'atmosphere' AND s.key = 'world_coherence';
INSERT INTO subcriterion_scores (evaluation_id, subcriterion_id, score, rationale, platform_note) SELECT (SELECT e.id FROM evaluations e JOIN games g ON g.id = e.game_id WHERE g.slug = 'redfall' AND e.version_number = 1), s.id, 0.5, 'Beyond the sky and the first walk through an abandoned house, very little of the experience leaves a distinct trace.', NULL FROM subcriteria s JOIN dimensions d ON d.id = s.dimension_id WHERE d.rubric_version = '1.0' AND d.key = 'atmosphere' AND s.key = 'memory_residue';
INSERT INTO subcriterion_scores (evaluation_id, subcriterion_id, score, rationale, platform_note) SELECT (SELECT e.id FROM evaluations e JOIN games g ON g.id = e.game_id WHERE g.slug = 'redfall' AND e.version_number = 1), s.id, 1, 'Gestures at cult power, wealth and a community abandoned by institutions, but never develops a position on any of them.', NULL FROM subcriteria s JOIN dimensions d ON d.id = s.dimension_id WHERE d.rubric_version = '1.0' AND d.key = 'thematic' AND s.key = 'thematic_clarity';
INSERT INTO subcriterion_scores (evaluation_id, subcriterion_id, score, rationale, platform_note) SELECT (SELECT e.id FROM evaluations e JOIN games g ON g.id = e.game_id WHERE g.slug = 'redfall' AND e.version_number = 1), s.id, 0.5, 'The abandoned homes carry a real flicker of loss. Nothing in the authored material builds on it.', NULL FROM subcriteria s JOIN dimensions d ON d.id = s.dimension_id WHERE d.rubric_version = '1.0' AND d.key = 'thematic' AND s.key = 'emotional_power';
INSERT INTO subcriterion_scores (evaluation_id, subcriterion_id, score, rationale, platform_note) SELECT (SELECT e.id FROM evaluations e JOIN games g ON g.id = e.game_id WHERE g.slug = 'redfall' AND e.version_number = 1), s.id, 1, 'The heroes are defined by ability kits rather than by any relationship to what the game is nominally about.', NULL FROM subcriteria s JOIN dimensions d ON d.id = s.dimension_id WHERE d.rubric_version = '1.0' AND d.key = 'thematic' AND s.key = 'theme_character_integration';
INSERT INTO subcriterion_scores (evaluation_id, subcriterion_id, score, rationale, platform_note) SELECT (SELECT e.id FROM evaluations e JOIN games g ON g.id = e.game_id WHERE g.slug = 'redfall' AND e.version_number = 1), s.id, 1, 'The vampire-as-predatory-elite idea is present and legible but stated rather than examined.', NULL FROM subcriteria s JOIN dimensions d ON d.id = s.dimension_id WHERE d.rubric_version = '1.0' AND d.key = 'thematic' AND s.key = 'philosophical_weight';
INSERT INTO subcriterion_scores (evaluation_id, subcriterion_id, score, rationale, platform_note) SELECT (SELECT e.id FROM evaluations e JOIN games g ON g.id = e.game_id WHERE g.slug = 'redfall' AND e.version_number = 1), s.id, 0.5, 'The game is remembered as a development story rather than for anything it says.', NULL FROM subcriteria s JOIN dimensions d ON d.id = s.dimension_id WHERE d.rubric_version = '1.0' AND d.key = 'thematic' AND s.key = 'lasting_impact';
INSERT INTO subcriterion_scores (evaluation_id, subcriterion_id, score, rationale, platform_note) SELECT (SELECT e.id FROM evaluations e JOIN games g ON g.id = e.game_id WHERE g.slug = 'redfall' AND e.version_number = 1), s.id, 1, 'UV light and stakes tie the mechanics to the fiction in an obvious, satisfying way, but that connection is the full extent of the integration.', NULL FROM subcriteria s JOIN dimensions d ON d.id = s.dimension_id WHERE d.rubric_version = '1.0' AND d.key = 'craft' AND s.key = 'mechanics_meaning';
INSERT INTO subcriterion_scores (evaluation_id, subcriterion_id, score, rationale, platform_note) SELECT (SELECT e.id FROM evaluations e JOIN games g ON g.id = e.game_id WHERE g.slug = 'redfall' AND e.version_number = 1), s.id, 0.5, 'Nothing in the game meaningfully revises what earlier actions meant.', NULL FROM subcriteria s JOIN dimensions d ON d.id = s.dimension_id WHERE d.rubric_version = '1.0' AND d.key = 'craft' AND s.key = 'player_recontextualization';
INSERT INTO subcriterion_scores (evaluation_id, subcriterion_id, score, rationale, platform_note) SELECT (SELECT e.id FROM evaluations e JOIN games g ON g.id = e.game_id WHERE g.slug = 'redfall' AND e.version_number = 1), s.id, 1, 'Entering houses and reconstructing what happened to their occupants is genuine interactive discovery, and it is the best-realised idea in the game.', NULL FROM subcriteria s JOIN dimensions d ON d.id = s.dimension_id WHERE d.rubric_version = '1.0' AND d.key = 'craft' AND s.key = 'interactive_revelation';
INSERT INTO subcriterion_scores (evaluation_id, subcriterion_id, score, rationale, platform_note) SELECT (SELECT e.id FROM evaluations e JOIN games g ON g.id = e.game_id WHERE g.slug = 'redfall' AND e.version_number = 1), s.id, 1, 'Exploring the town yourself matters; almost everything else would survive translation to another medium unchanged.', NULL FROM subcriteria s JOIN dimensions d ON d.id = s.dimension_id WHERE d.rubric_version = '1.0' AND d.key = 'craft' AND s.key = 'medium_irreplaceability';
INSERT INTO subcriterion_scores (evaluation_id, subcriterion_id, score, rationale, platform_note) SELECT (SELECT e.id FROM evaluations e JOIN games g ON g.id = e.game_id WHERE g.slug = 'redfall' AND e.version_number = 1), s.id, 1, 'Approach and loadout choices exist but carry no consequence beyond the current fight.', NULL FROM subcriteria s JOIN dimensions d ON d.id = s.dimension_id WHERE d.rubric_version = '1.0' AND d.key = 'craft' AND s.key = 'meaningful_agency';
