INSERT INTO profile_blocks (evaluation_id, block_type, item_order, text) VALUES ((SELECT e.id FROM evaluations e JOIN games g ON g.id = e.game_id WHERE g.slug = 'redfall' AND e.version_number = 1), 'probably_not', 1, 'You expect Dishonored or Prey-style systemic creativity.');
